contract InvMutTest {
    C c;
    address deployer;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // The single public test function. We take parameters that attempt to withdraw or send.
    function run(address target, uint256 value, bytes calldata data) public payable {
        require(true);

        // Observe before-values
        uint256 beforeBalance = address(c).balance;
        uint256 beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // Attempt withdraw (may revert). We are NOT the owner if the testing harness deploys C with a different deployer.
        bool withdrewReverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrewReverted = true;
        } else {
            withdrewReverted = false;
        }

        // Attempt withdrawAll
        bool withdrawAllReverted;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            withdrawAllReverted = true;
        } else {
            withdrawAllReverted = false;
        }

        // Attempt sendMoney with some value; if we need to send Ether to c for this call, ensure balance
        // We will not send Ether from this contract to c here. Call without forwarded value because sendMoney uses call to target.
        bool sendMoneyReverted;
        c.sendMoney(target, value, data); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            sendMoneyReverted = true;
        } else {
            sendMoneyReverted = false;
        }

        // Observe after-values
        uint256 afterBalance = address(c).balance;
        uint256 afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // General rule: if any of these privileged calls reverted then c's balance and depositsCount did not decrease
        // and if none reverted (i.e., the caller was owner) then balance may have decreased but depositsCount is unchanged except via fallback.
        // Expressed as: if caller is not owner then all three calls must revert and both observed values unchanged.

        // Read owner via public getter
        address owner = c.owner(); if (__ESBMC_reverted()) return;

        // Build assertion: if this contract is not owner then all calls reverted and balances unchanged
        assert( (address(this) != owner) ? (
            withdrewReverted && withdrawAllReverted && sendMoneyReverted && afterBalance == beforeBalance && afterDeposits == beforeDeposits
        ) : (
            // If this is owner, then at least no unexpected increase in depositsCount occurred from these calls (fallback increments only on plain Ether reception),
            // and balance is either unchanged or decreased by at most the sum of requested withdraws/sendMoney values.
            // We cannot compute exact transfers for external call, so require depositsCount didn't decrease.
            afterDeposits >= beforeDeposits
        ) );
    }

    // allow receiving Ether in case owner operations send here
    receive() external payable {}
}

