    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;
    address deployer;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address target, uint256 value, bytes memory data) internal {
        vm.assume(true);
        uint256 beforeBalance = address(c).balance;
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        bool withdrewReverted;
        try c.withdraw(value) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }
        bool sendMoneyReverted;
        try c.sendMoney(target, value, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }
        uint256 afterBalance = address(c).balance;
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        assertTrue((address(this) != owner) ? (
            withdrewReverted && withdrawAllReverted && sendMoneyReverted && afterBalance == beforeBalance && afterDeposits == beforeDeposits
        ) : (
            // If this is owner, then at least no unexpected increase in depositsCount occurred from these calls (fallback increments only on plain Ether reception),
            // and balance is either unchanged or decreased by at most the sum of requested withdraws/sendMoney values.
            // We cannot compute exact transfers for external call, so require depositsCount didn't decrease.
            afterDeposits >= beforeDeposits
        ));
    }

    function testFuzz_run(address target, uint256 value, bytes memory data) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(target, value, data);
    }

    receive() external payable {}
}
